let db=loadData(),currentPage='dashboard',employeeFilter='All',employeeQuery='',recruitmentFilter='All roles',saveQueue=Promise.resolve(),apiReady=false,csrfToken='',currentUser=null,settingsTab='workspace',lastSavedSnapshot='',chartMonths=6;
function loadData(){return structuredClone(seed)}
function saveData(){if(!apiReady)return;let snapshot=JSON.stringify(db);saveQueue=saveQueue.then(async()=>{let response=await fetch('/api/data',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:snapshot}),result=await response.json().catch(()=>({error:'The server returned an invalid response.'}));if(!response.ok){let error=new Error(result.error||'Save failed');error.status=response.status;throw error}lastSavedSnapshot=snapshot}).catch(error=>{if(error.status===401||error.status===403)apiReady=false;if(lastSavedSnapshot)db=JSON.parse(lastSavedSnapshot);toast(error.message||'Could not save to the server.',false);console.error(error);if(currentUser)render()})}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function initials(n='?'){return n.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function money(n){let currency=db.settings?.[0]?.currency||'USD';try{return new Intl.NumberFormat(undefined,{style:'currency',currency,maximumFractionDigits:0}).format(Number(n||0))}catch{return '$'+Number(n||0).toLocaleString('en-US')}}
function avatar(name,color='purple',size=''){return `<span class="avatar avatar-${esc(color)} ${size}">${esc(initials(name))}</span>`}
function pill(s='—'){let label=String(s||'—'),c=label.toLowerCase().replace(/\s+/g,'-');return `<span class="status-pill status-${esc(c)}">${esc(label)}</span>`}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">PEOPLE OPERATIONS</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function setPage(page){currentPage=page;document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===page));document.getElementById('breadcrumbTitle').textContent=({dashboard:'Overview',employees:'Employees',recruitment:'Recruitment',payroll:'Payroll',performance:'Performance',leave:'Time off',onboarding:'Onboarding',analytics:'Analytics',settings:'Settings',team:'Team access',help:'Help & support'})[page]||'Overview';document.getElementById('sidebar').classList.remove('open');render();location.hash=page}
function render(){let host=document.getElementById('pageContent');const pages={dashboard:dashboardPage,employees:employeesPage,recruitment:recruitmentPage,payroll:payrollPage,performance:performancePage,leave:leavePage,onboarding:onboardingPage,analytics:analyticsPage,settings:settingsTabPage,team:teamPage,help:helpPage};try{host.innerHTML=(pages[currentPage]||dashboardPage)()}catch(error){console.error(`Could not render ${currentPage}:`,error);host.innerHTML='<section class="panel"><h2 class="panel-title">This page could not be displayed</h2><p class="panel-subtitle">Your workspace is still available. Refresh the page or contact an administrator if this continues.</p></section>';return}document.getElementById('employeeNavCount').textContent=db.employees.filter(x=>x.status==='Active').length;if(currentPage==='dashboard')drawChart();if(currentPage==='analytics')drawAnalyticsCharts();if(currentPage==='team')loadTeam()}
function greetingForLocalTime(){let hour=new Date().getHours();return hour<12?'Good morning ☀️':hour<17?'Good afternoon ☀️':'Good evening 🌙'}
function dashboardPage(){let active=db.employees.filter(x=>x.status==='Active').length,departments=['Engineering','Design','Marketing','People','Finance','Sales'],colors=['#695be0','#8b7fe9','#a89ff0','#bcb7f4','#d0cdf7','#e0defa'];let depts=departments.map((d,i)=>{let n=db.employees.filter(e=>e.department===d&&e.status==='Active').length;return `<div class="dept-row"><span>${d}</span><div class="dept-bar"><div class="dept-fill" style="width:${Math.max(3,n/Math.max(active,1)*100)}%;background:${colors[i]}"></div></div><strong>${n}</strong></div>`}).join('');let recent=db.employees.slice(0,5),activities=[...db.employees.map(x=>({icon:'♙',date:x.joined,label:`<strong>${esc(x.name)}</strong> joined ${esc(x.department||'the team')}`})),...db.candidates.map(x=>({icon:'⌕',date:x.createdAt||x.date,label:`<strong>${esc(x.name)}</strong> entered the ${esc(x.role)} pipeline`})),...db.payruns.map(x=>({icon:'▤',date:x.payDate,label:`${esc(x.period)} payroll · ${esc(x.status)}`})),...db.leaves.map(x=>({icon:'☼',date:x.createdAt||x.start,label:`<strong>${esc(x.employee)}</strong> leave request · ${esc(x.status)}`})),...db.onboarding.map(x=>({icon:'✦',date:x.startDate,label:`<strong>${esc(x.name)}</strong> onboarding started`}))].sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0));return `${heading(`${greetingForLocalTime()}, ${esc(currentUser?.name?.split(/\s+/)[0]||'there')}`,'Here’s what’s happening with your team today.',`<button class="button" id="exportEmployees">↧ &nbsp;Export</button><button class="button primary" data-action="add-employee"><span class="plus">+</span> Add employee</button>`)}
<div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>Total employees</span><span class="stat-icon icon-purple">♙</span></div><div class="stat-value">${db.employees.length}</div><div class="stat-foot">In your employee directory</div></article><article class="stat-card"><div class="stat-top"><span>Roles in pipeline</span><span class="stat-icon icon-blue">⌕</span></div><div class="stat-value">${new Set(db.candidates.map(c=>c.role)).size}</div><div class="stat-foot">Distinct roles with candidates</div></article><article class="stat-card"><div class="stat-top"><span>On leave</span><span class="stat-icon icon-orange">☼</span></div><div class="stat-value">${db.employees.filter(e=>e.status==='On leave').length}</div><div class="stat-foot"><span>Across ${new Set(db.employees.filter(e=>e.status==='On leave').map(e=>e.department)).size} departments</span></div></article><article class="stat-card"><div class="stat-top"><span>Inactive employees</span><span class="stat-icon icon-green">♧</span></div><div class="stat-value">${db.employees.filter(e=>e.status==='Inactive').length}</div><div class="stat-foot">Marked inactive in your directory</div></article></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Workforce overview</h2><div class="panel-subtitle">Headcount and hiring activity over time</div></div><select class="period-select" id="chartPeriod"><option>Last 6 months</option><option>Last 12 months</option></select></div><div class="chart-legend"><span class="legend-item"><i class="legend-dot"></i>Headcount</span><span class="legend-item"><i class="legend-dot alt"></i>New hires</span></div><div class="chart-wrap"><canvas id="workforceChart"></canvas><div class="chart-tooltip" id="chartTooltip"></div></div></section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Team by department</h2><div class="panel-subtitle">Active employee distribution</div></div><a href="#analytics" class="text-link" data-page="analytics">View all ↗</a></div><div class="dept-list">${depts}</div><div class="dept-total"><span>Total active employees</span><strong>${active}</strong></div></section></div>
<div class="bottom-grid"><section class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Recent employees</h2><div class="panel-subtitle">Your latest team additions</div></div><a class="text-link" href="#employees" data-page="employees">View directory ↗</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>JOINED</th><th>STATUS</th></tr></thead><tbody>${recent.map(e=>`<tr><td><div class="person-cell">${avatar(e.name,e.color)}<div><div class="person-name">${esc(e.name)}</div><div class="person-role">${esc(e.role)}</div></div></div></td><td>${esc(e.department)}</td><td>${dateShort(e.joined)}</td><td>${pill(e.status)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Recent activity</h2><div class="panel-subtitle">A little bit of everything</div></div><button class="row-actions" aria-label="More">•••</button></div><div class="activity-list">${activities.length?activities.slice(0,4).map(x=>`<div class="activity-item"><span class="activity-icon">${x.icon}</span><div class="activity-copy">${x.label}<div class="activity-time">${(/^\d{4}-\d{2}-\d{2}/.test(String(x.date||''))?dateShort(String(x.date).slice(0,10)):esc(x.date||'—'))}</div></div></div>`).join(''):'<div class="empty-state">Team activity will appear here as your workspace gets started.</div>'}</div></section></div>`}
function dateShort(s){if(!s)return '—';let format=db.settings?.[0]?.dateFormat||'MMM d, yyyy';if(format==='yyyy-MM-dd')return String(s).slice(0,10);let d=new Date(String(s).slice(0,10)+'T00:00:00');if(format==='dd/MM/yyyy')return d.toLocaleDateString('en-GB');if(format==='MM/dd/yyyy')return d.toLocaleDateString('en-US');return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function employeesPage(){let list=db.employees.filter(e=>(employeeFilter==='All'||e.status===employeeFilter)&&(!employeeQuery||`${e.name} ${e.role} ${e.department} ${e.email}`.toLowerCase().includes(employeeQuery.toLowerCase())));return `${heading('Employee directory','All your people, in one place.',`<button class="button" id="exportEmployees">↧ &nbsp;Export</button><button class="button primary" data-action="add-employee"><span class="plus">+</span> Add employee</button>`)}<section class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">All employees <span style="color:#a1a2b2;font-weight:500">(${list.length})</span></h2><div class="panel-subtitle">Manage your team and employee records</div></div><div class="table-toolbar"><label class="table-search"><span>⌕</span><input id="employeeSearch" placeholder="Search employees..." value="${esc(employeeQuery)}"></label><select class="filter-select" id="employeeFilter"><option ${employeeFilter==='All'?'selected':''}>All</option><option ${employeeFilter==='Active'?'selected':''}>Active</option><option ${employeeFilter==='On leave'?'selected':''}>On leave</option><option ${employeeFilter==='Inactive'?'selected':''}>Inactive</option></select></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>EMPLOYEE ID</th><th>DEPARTMENT</th><th>LOCATION</th><th>JOINED</th><th>STATUS</th><th></th></tr></thead><tbody>${list.length?list.map(e=>`<tr><td><div class="person-cell">${avatar(e.name,e.color)}<div><div class="person-name">${esc(e.name)}</div><div class="person-role">${esc(e.email)}</div></div></div></td><td>${esc(e.id)}</td><td>${esc(e.department)}</td><td>${esc(e.location)}</td><td>${dateShort(e.joined)}</td><td>${pill(e.status)}</td><td><button class="row-actions" data-action="employee-menu" data-id="${esc(e.id)}">•••</button></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty-state">No employees match this search.</div></td></tr>`}</tbody></table></div><div class="pagination"><span>Showing ${list.length?1:0}–${list.length} of ${list.length} employees</span><div class="pagination-controls"><button>‹</button><button class="current">1</button><button>›</button></div></div></section>`}
function recruitmentPage(){let stages=['Applied','Screening','Interview','Offer'];let roles=['All roles',...new Set(db.candidates.map(x=>x.role))];return `${heading('Recruitment','Find great people and make every first impression count.',`<button class="button">⚙ &nbsp;Pipeline settings</button><button class="button primary" data-action="add-candidate"><span class="plus">+</span> Add candidate</button>`)}<div class="stats-grid"><article class="stat-card"><div class="stat-top">Roles in pipeline<span class="stat-icon icon-purple">⌕</span></div><div class="stat-value">${new Set(db.candidates.map(c=>c.role)).size}</div><div class="stat-foot">Distinct roles with candidates</div></article><article class="stat-card"><div class="stat-top">Active candidates<span class="stat-icon icon-blue">♙</span></div><div class="stat-value">${db.candidates.length}</div><div class="stat-foot">Currently in the hiring pipeline</div></article><article class="stat-card"><div class="stat-top">In interviews<span class="stat-icon icon-orange">◷</span></div><div class="stat-value">${db.candidates.filter(c=>c.stage==='Interview').length}</div><div class="stat-foot">Candidates at interview stage</div></article><article class="stat-card"><div class="stat-top">Offers pending<span class="stat-icon icon-green">✓</span></div><div class="stat-value">${db.candidates.filter(c=>c.stage==='Offer').length}</div><div class="stat-foot">Candidates awaiting an offer decision</div></article></div><div class="panel" style="padding:15px 17px;margin-bottom:13px;display:flex;align-items:center;justify-content:space-between"><div><strong style="font-size:11px">Hiring pipeline</strong><span style="font-size:10px;color:#a0a1b0;margin-left:8px">Candidates grouped by stage</span></div><select class="filter-select" id="roleFilter">${roles.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="kanban">${stages.map(st=>{let candidates=db.candidates.filter(c=>c.stage===st&&(recruitmentFilter==='All roles'||c.role===recruitmentFilter));return `<section class="kanban-column"><div class="kanban-head"><span>${st}</span><span>${candidates.length}</span></div>${candidates.length?candidates.map(c=>`<article class="candidate-card"><div class="candidate-head">${avatar(c.name,c.color)}<div><div class="candidate-name">${esc(c.name)}</div><div class="candidate-job">${esc(c.role)}</div></div><button class="row-actions" data-action="candidate-menu" data-id="${c.id}">•••</button></div><div class="candidate-meta"><span>Applied ${esc(c.date)}</span><span>Match ${esc(c.score)}</span></div><div class="candidate-actions"><button class="button" data-action="candidate-stage" data-id="${c.id}">Move stage →</button></div></article>`).join(''):`<div class="empty-state">No candidates</div>`}</section>`}).join('')}</div>`}
function payrollPage(){let total=db.employees.filter(e=>e.status==='Active').reduce((s,e)=>s+Number(e.salary||0),0),runs=(db.payruns||[]).slice().sort((a,b)=>b.payDate.localeCompare(a.payDate));return `${heading('Payroll','A clear view of compensation and pay runs.',`<button class="button" id="payrollExport">↧ &nbsp;Export report</button><button class="button primary" data-action="run-payroll">▤ &nbsp;Run payroll</button>`)}<div class="payroll-summary"><article class="panel payroll-mini"><span>Monthly payroll</span><strong>${money(total/12)}</strong><small>Estimated gross · ${db.employees.filter(e=>e.status==='Active').length} employees</small></article><article class="panel payroll-mini"><span>Next pay date</span><strong>End of month</strong><small>Monthly cycle · draft run for review</small></article><article class="panel payroll-mini"><span>Pending approvals</span><strong>${runs.filter(r=>r.status==='Draft').length}</strong><small>Draft payroll runs</small></article></div><section class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Recent pay runs</h2><div class="panel-subtitle">Track payroll history and upcoming payments</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>PAY PERIOD</th><th>EMPLOYEES</th><th>GROSS PAY</th><th>PAY DATE</th><th>STATUS</th><th></th></tr></thead><tbody>${runs.length?runs.map(r=>`<tr><td><strong>${esc(r.period)}</strong></td><td>${r.employees} employees</td><td>${money(r.gross)}</td><td>${dateShort(r.payDate)}</td><td>${pill(r.status)}</td><td>${r.status==='Draft'?`<button class="button" data-action="approve-payroll" data-id="${esc(r.id)}">Approve</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6"><div class="empty-state">No pay runs yet.</div></td></tr>`}</tbody></table></div></section><section class="panel" style="margin-top:15px"><div class="panel-header"><div><h2 class="panel-title">Salary overview</h2><div class="panel-subtitle">Annual salary by department</div></div><button class="button" id="salaryExport">↧ Export CSV</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>DEPARTMENT</th><th>EMPLOYEES</th><th>AVERAGE SALARY</th><th>ANNUAL TOTAL</th></tr></thead><tbody>${[...new Set(db.employees.map(e=>e.department))].map(d=>{let a=db.employees.filter(e=>e.department===d&&e.status==='Active'),sum=a.reduce((s,e)=>s+Number(e.salary||0),0);return `<tr><td><strong>${esc(d)}</strong></td><td>${a.length}</td><td>${money(a.length?sum/a.length:0)}</td><td>${money(sum)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function performancePage(){let averageReview=db.reviews.length?db.reviews.reduce((sum,r)=>sum+Number(r.score||0),0)/db.reviews.length:null;return `${heading('Performance','Help every person do their best work.',`<select class="period-select"><option>Q3 2026</option><option>Q2 2026</option></select><button class="button primary" data-action="add-goal"><span class="plus">+</span> Add goal</button>`)}<div class="performance-cards"><article class="panel review-card"><div class="stat-top">Company average <span class="stat-icon icon-purple">✦</span></div><div class="review-score">${averageReview===null?'—':averageReview.toFixed(1)} <span style="font-size:11px;color:#9a9bab;font-weight:500">/ 5.0</span></div><div class="score-stars">${averageReview===null?'No ratings yet':'★'.repeat(Math.max(1,Math.round(averageReview)))}</div></article><article class="panel review-card"><div class="stat-top">Reviews completed <span class="stat-icon icon-blue">✓</span></div><div class="review-score">${Math.round(db.reviews.length/Math.max(db.employees.length,1)*100)}%</div><div class="stat-foot">${db.reviews.length} of ${db.employees.length} team members</div></article><article class="panel review-card"><div class="stat-top">Goals on track <span class="stat-icon icon-green">↗</span></div><div class="review-score">${db.goals.filter(g=>g.progress>=70).length}<span style="font-size:11px;color:#9a9bab;font-weight:500"> / ${db.goals.length} goals</span></div><div class="stat-foot">Keep up the great work</div></article></div><div class="bottom-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Team reviews</h2><div class="panel-subtitle">Latest quarterly performance reviews</div></div><button class="text-link" data-action="add-review">+ Add review</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>RATING</th><th>GOAL PROGRESS</th><th>REVIEW</th></tr></thead><tbody>${db.reviews.map(r=>`<tr><td><div class="person-cell">${avatar(r.name,r.color)}<div><div class="person-name">${esc(r.name)}</div><div class="person-role">${esc(r.role)}</div></div></div></td><td><strong>${r.score.toFixed(1)}</strong> <span class="score-stars">★</span></td><td>${r.progress}%</td><td>${pill('Completed')}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Team goals</h2><div class="panel-subtitle">Company objectives for Q3</div></div></div>${db.goals.map(g=>`<div class="goal-row"><div><strong>${esc(g.title)}</strong><div class="person-role" style="margin-top:4px">${esc(g.owner)}</div></div><div class="goal-track"><div class="goal-progress" style="width:${g.progress}%"></div></div><strong>${g.progress}%</strong></div>`).join('')}</section></div>`}
function leavePage(){let pending=db.leaves.filter(l=>l.status==='Pending').length;return `${heading('Time off','Keep leave requests and approvals in one clear place.',`<button class="button primary" data-action="add-leave"><span class="plus">+</span> Request time off</button>`)}<div class="stats-grid"><article class="stat-card"><div class="stat-top">Pending requests<span class="stat-icon icon-orange">◷</span></div><div class="stat-value">${pending}</div><div class="stat-foot">Waiting for a decision</div></article><article class="stat-card"><div class="stat-top">Approved this year<span class="stat-icon icon-green">✓</span></div><div class="stat-value">${db.leaves.filter(l=>l.status==='Approved').length}</div><div class="stat-foot">Leave requests</div></article><article class="stat-card"><div class="stat-top">People currently away<span class="stat-icon icon-blue">☼</span></div><div class="stat-value">${db.employees.filter(e=>e.status==='On leave').length}</div><div class="stat-foot">Employee status records</div></article><article class="stat-card"><div class="stat-top">Leave types<span class="stat-icon icon-purple">≋</span></div><div class="stat-value">4</div><div class="stat-foot">Annual · sick · personal · unpaid</div></article></div><section class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Leave requests</h2><div class="panel-subtitle">Review dates and approve or decline requests.</div></div><select class="filter-select" id="leaveFilter"><option>All requests</option><option>Pending</option><option>Approved</option><option>Declined</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>TYPE</th><th>DATES</th><th>DAYS</th><th>STATUS</th><th></th></tr></thead><tbody id="leaveRows">${leaveRows('All requests')}</tbody></table></div></section>`}
function leaveRows(filter){let list=db.leaves.filter(l=>filter==='All requests'||l.status===filter);return list.length?list.map(l=>`<tr><td><div class="person-cell">${avatar(l.employee,l.color||'purple')}<div><div class="person-name">${esc(l.employee)}</div><div class="person-role">Requested ${dateShort(l.createdAt)}</div></div></div></td><td>${esc(l.type)}</td><td>${dateShort(l.start)} – ${dateShort(l.end)}</td><td>${Number(l.days)||1}</td><td>${pill(l.status)}</td><td>${l.status==='Pending'?`<button class="button" data-action="leave-decision" data-id="${esc(l.id)}" data-status="Approved">Approve</button> <button class="button" data-action="leave-decision" data-id="${esc(l.id)}" data-status="Declined">Decline</button>`:''}</td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state">No leave requests here yet.</div></td></tr>'}
function onboardingPage(){return `${heading('Onboarding','Give each new teammate a smooth, consistent start.',`<button class="button primary" data-action="add-onboarding"><span class="plus">+</span> Start onboarding</button>`)}<div class="stats-grid"><article class="stat-card"><div class="stat-top">New starters<span class="stat-icon icon-purple">♙</span></div><div class="stat-value">${db.onboarding.length}</div><div class="stat-foot">People in onboarding</div></article><article class="stat-card"><div class="stat-top">Tasks to complete<span class="stat-icon icon-orange">◷</span></div><div class="stat-value">${db.onboarding.reduce((s,o)=>s+o.tasks.filter(t=>!t.done).length,0)}</div><div class="stat-foot">Across all new starters</div></article><article class="stat-card"><div class="stat-top">Completed tasks<span class="stat-icon icon-green">✓</span></div><div class="stat-value">${db.onboarding.reduce((s,o)=>s+o.tasks.filter(t=>t.done).length,0)}</div><div class="stat-foot">Welcome aboard</div></article><article class="stat-card"><div class="stat-top">Active employees<span class="stat-icon icon-blue">♧</span></div><div class="stat-value">${db.employees.filter(e=>e.status==='Active').length}</div><div class="stat-foot">In your directory</div></article></div><div class="analytics-grid">${db.onboarding.length?db.onboarding.map(o=>{let done=o.tasks.filter(t=>t.done).length,total=o.tasks.length;return `<section class="panel analytics-card"><div class="panel-header"><div><h2 class="panel-title">${esc(o.name)}</h2><div class="panel-subtitle">${esc(o.role)} · starts ${dateShort(o.startDate)}</div></div><span class="status-pill status-in-progress">${done}/${total} complete</span></div>${o.tasks.map((t,i)=>`<label class="settings-row onboarding-task"><span><strong>${esc(t.title)}</strong></span><input type="checkbox" data-action="onboarding-task" data-id="${esc(o.id)}" data-index="${i}" ${t.done?'checked':''}></label>`).join('')}<button class="button" data-action="complete-onboarding" data-id="${esc(o.id)}">Add to employee directory</button></section>`}).join(''):'<section class="panel analytics-card"><h2 class="panel-title">No one in onboarding yet</h2><p class="panel-subtitle">Create a checklist for your next new starter.</p><button class="button primary" data-action="add-onboarding">Start onboarding</button></section>'}</div>`}
function analyticsPage(){let active=db.employees.filter(e=>e.status==='Active'),avg=active.length?Math.round(active.reduce((s,e)=>s+Number(e.salary||0),0)/active.length):0,tenure=active.map(e=>Date.parse(`${e.joined}T00:00:00Z`)).filter(Number.isFinite),avgTenure=tenure.length?(tenure.reduce((sum,date)=>sum+Math.max(0,Date.now()-date),0)/tenure.length/31557600000).toFixed(1):null;return `${heading('People analytics','A pulse check on your team and how it’s growing.',`<select class="period-select" id="analyticsPeriod"><option>Year to date</option><option>Last 12 months</option></select><button class="button" id="analyticsExport">↧ &nbsp;Export report</button>`)}<div class="stats-grid"><article class="stat-card"><div class="stat-top">Headcount <span class="stat-icon icon-purple">♙</span></div><div class="stat-value">${active.length}</div><div class="stat-foot">Current employee records</div></article><article class="stat-card"><div class="stat-top">Avg. tenure <span class="stat-icon icon-blue">◷</span></div><div class="stat-value">${avgTenure===null?'—':`${avgTenure} <small style="font-size:12px">yrs</small>`}</div><div class="stat-foot">Average for current active employees</div></article><article class="stat-card"><div class="stat-top">Avg. salary <span class="stat-icon icon-orange">＄</span></div><div class="stat-value">${money(avg)}</div><div class="stat-foot">Annual · active employees</div></article><article class="stat-card"><div class="stat-top">Inactive employees <span class="stat-icon icon-green">♧</span></div><div class="stat-value">${db.employees.filter(e=>e.status==='Inactive').length}</div><div class="stat-foot">Marked inactive in the directory</div></article></div><div class="analytics-grid"><section class="panel analytics-card"><div class="panel-header"><div><h2 class="panel-title">Headcount growth</h2><div class="panel-subtitle">Team size by month</div></div></div><div class="chart-wrap"><canvas id="analyticsHeadcount"></canvas></div></section><section class="panel analytics-card"><div class="panel-header"><div><h2 class="panel-title">Department mix</h2><div class="panel-subtitle">Current active employees</div></div></div><div class="chart-wrap"><canvas id="analyticsDepartments"></canvas></div></section><section class="panel analytics-card"><div class="panel-header"><div><h2 class="panel-title">Hiring funnel</h2><div class="panel-subtitle">Candidates across recruiting stages</div></div></div>${['Applied','Screening','Interview','Offer'].map((s,i)=>{let n=db.candidates.filter(c=>c.stage===s).length;return `<div class="goal-row"><strong>${s}</strong><div class="goal-track"><div class="goal-progress" style="width:${Math.max(5,n/Math.max(db.candidates.length,1)*100)}%"></div></div><strong>${n}</strong></div>`}).join('')}</section><section class="panel analytics-card"><div class="panel-header"><div><h2 class="panel-title">Location distribution</h2><div class="panel-subtitle">Where your people work</div></div></div>${[...new Set(db.employees.map(e=>e.location))].map(l=>{let n=db.employees.filter(e=>e.location===l).length;return `<div class="goal-row"><strong>${esc(l)}</strong><div class="goal-track"><div class="goal-progress" style="width:${n/Math.max(db.employees.length,1)*100}%"></div></div><strong>${n}</strong></div>`}).join('')}</section></div>`}
function settingsTabPage(){let s=workspaceSettings(),tabs=[['workspace','Workspace'],['company','Company profile'],['notifications','Notifications'],['security','Security'],['integrations','Integrations']],titles={workspace:'Workspace preferences',company:'Company profile',notifications:'Notification preferences',security:'Account security',integrations:'Data integrations'},descriptions={workspace:'Set the defaults your team uses across HRGenius.',company:'Keep your organization details current.',notifications:'Choose which HRGenius reminders you want to receive.',security:'Manage your password and sign-in sessions.',integrations:'Export your workspace data or connect it to your calendar.'};let actions=['workspace','company','notifications'].includes(settingsTab)?'<button class="button primary" id="saveSettings" type="submit" form="settingsForm">Save changes</button>':'';let body='';if(settingsTab==='workspace')body=`<div class="form-grid settings-form-grid"><div class="form-field full"><label>Workspace name</label><input name="companyName" required minlength="2" maxlength="120" value="${esc(s.companyName)}"></div><div class="form-field"><label>Time zone</label><select name="timezone">${['Asia/Kolkata','America/New_York','America/Los_Angeles','Europe/London','UTC'].map(x=>`<option ${s.timezone===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Default currency</label><select name="currency">${[['USD','US Dollar ($)'],['INR','Indian Rupee (₹)'],['EUR','Euro (€)'],['GBP','Pound Sterling (£)'],['CAD','Canadian Dollar ($)'],['AUD','Australian Dollar ($)']].map(([v,l])=>`<option value="${v}" ${s.currency===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-field"><label>Date format</label><select name="dateFormat">${['MMM d, yyyy','dd/MM/yyyy','MM/dd/yyyy','yyyy-MM-dd'].map(x=>`<option ${s.dateFormat===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Week starts on</label><select name="weekStart"><option ${s.weekStart==='Monday'?'selected':''}>Monday</option><option ${s.weekStart==='Sunday'?'selected':''}>Sunday</option></select></div></div>`;if(settingsTab==='company')body=`<div class="form-grid settings-form-grid"><div class="form-field"><label>Legal company name</label><input name="legalName" maxlength="160" value="${esc(s.legalName)}" placeholder="Registered business name"></div><div class="form-field"><label>Industry</label><input name="industry" maxlength="100" value="${esc(s.industry)}" placeholder="e.g. Technology"></div><div class="form-field"><label>Website</label><input name="website" type="url" maxlength="200" value="${esc(s.website)}" placeholder="https://example.com"></div><div class="form-field"><label>Team size</label><select name="teamSize">${['1-10','11-50','51-200','201-500','501+'].map(x=>`<option ${s.teamSize===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Headquarters</label><input name="headquarters" maxlength="120" value="${esc(s.headquarters)}" placeholder="City, country"></div><div class="form-field"><label>HR contact email</label><input name="contactEmail" type="email" maxlength="254" value="${esc(s.contactEmail)}" placeholder="people@example.com"></div></div>`;if(settingsTab==='notifications')body=[['weeklySummary','Weekly summary','Get a digest of your team activity each week.'],['hiring','Hiring updates','Receive updates when a candidate moves through the pipeline.'],['reviews','Review reminders','Remind managers about upcoming performance reviews.'],['payroll','Payroll alerts','Get notified when payroll is ready for approval.']].map(([key,title,desc])=>`<label class="settings-row"><span><strong>${title}</strong><p>${desc}</p></span><input class="toggle-input" type="checkbox" name="notify_${key}" ${s.notifications[key]?'checked':''} aria-label="${title}"></label>`).join('');if(settingsTab==='security')body=`<p class="settings-help">Signed in as <strong>${esc(currentUser?.email||'')}</strong>. Sessions expire after 14 days. Changing your password signs out other active sessions.</p><form id="changePasswordForm" class="form-grid" style="margin-top:18px"><div class="form-field full"><label for="currentPassword">Current password</label><input id="currentPassword" name="currentPassword" type="password" autocomplete="current-password" required></div><div class="form-field full"><label for="newPassword">New password</label><input id="newPassword" name="newPassword" type="password" autocomplete="new-password" minlength="12" required></div><div class="form-field full"><button class="button primary" type="submit" style="width:max-content">Update password</button></div></form>`;if(settingsTab==='integrations')body=`<p class="settings-help">These built-in exports work now and include only this workspace's records. Keep downloaded HR and payroll files somewhere private.</p><div class="settings-integration"><div><strong>Employee directory</strong><p>Download employee records as a spreadsheet.</p></div><button class="button" data-settings-export="employees">Export CSV</button></div><div class="settings-integration"><div><strong>Payroll report</strong><p>Export pay runs and pay dates.</p></div><button class="button" data-settings-export="payroll">Export CSV</button></div><div class="settings-integration"><div><strong>Leave calendar</strong><p>Add approved time off to a calendar app using an ICS file.</p></div><button class="button" data-settings-export="calendar">Download ICS</button></div><div class="settings-integration"><div><strong>Workspace backup</strong><p>Download all workspace HR records as a JSON backup.</p></div><button class="button" data-settings-export="backup">Download JSON</button></div><div class="settings-integration"><div><strong>Third-party connections</strong><p>HRGenius does not currently have external provider credentials configured.</p></div><span class="status-pill status-inactive">Not connected</span></div>`;return `${heading('Settings','Manage your workspace preferences and account.',actions)}<div class="settings-grid"><nav class="panel settings-nav" aria-label="Settings sections">${tabs.map(([id,label])=>`<button type="button" data-settings-tab="${id}" class="${settingsTab===id?'active':''}" aria-current="${settingsTab===id?'page':'false'}">${label}</button>`).join('')}</nav><section class="panel settings-content"><h2 class="panel-title">${titles[settingsTab]}</h2><div class="panel-subtitle">${descriptions[settingsTab]}</div>${['workspace','company','notifications'].includes(settingsTab)?`<form id="settingsForm" style="margin-top:18px">${body}</form>`:body}</section></div>`}
function workspaceSettings(){if(!Array.isArray(db.settings))db.settings=[];if(!db.settings[0])db.settings[0]={id:'workspace',companyName:currentUser?.company||'My workspace',timezone:'UTC',currency:'USD',dateFormat:'MMM d, yyyy',weekStart:'Monday',legalName:'',industry:'',website:'',teamSize:'1-10',headquarters:'',contactEmail:'',notifications:{weeklySummary:true,hiring:true,reviews:false,payroll:true}};db.settings[0].notifications={weeklySummary:true,hiring:true,reviews:false,payroll:true,...(db.settings[0].notifications||{})};return db.settings[0]}
async function saveSettingsForm(form){let values=Object.fromEntries(new FormData(form).entries()),s=workspaceSettings();try{for(let key of ['companyName','timezone','currency','dateFormat','weekStart','legalName','industry','website','teamSize','headquarters','contactEmail'])if(key in values)s[key]=String(values[key]).trim();if(settingsTab==='notifications')s.notifications={weeklySummary:'notify_weeklySummary'in values,hiring:'notify_hiring'in values,reviews:'notify_reviews'in values,payroll:'notify_payroll'in values};if(settingsTab==='workspace'&&s.companyName!==currentUser.company){let result=await apiRequest('/api/workspace',{method:'PATCH',body:JSON.stringify({company:s.companyName})});currentUser.company=result.company;document.querySelector('.workspace-copy strong').textContent=result.company;document.getElementById('workspaceCrumb').textContent=result.company}await apiRequest('/api/data',{method:'PUT',body:JSON.stringify(db)});lastSavedSnapshot=JSON.stringify(db);document.querySelectorAll('.workspace-avatar').forEach(el=>el.textContent=initials(currentUser.company));toast('Settings saved');render()}catch(error){toast(error.message||'Could not save settings.',false)}}
function teamPage(){return `${heading('Team access',`Invite colleagues to ${esc(currentUser?.company||'your workspace')} and manage their access.`,`<button class="button primary" data-action="invite-member"><span class="plus">+</span> Invite teammate</button>`)}<section class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Workspace members</h2><div class="panel-subtitle">Admins and HR managers can access employee and payroll records.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>MEMBER</th><th>EMAIL</th><th>ROLE</th><th>JOINED</th><th></th></tr></thead><tbody id="teamRows"><tr><td colspan="5"><div class="empty-state">Loading team members…</div></td></tr></tbody></table></div></section><section class="panel" style="margin-top:14px;padding:15px 18px"><h2 class="panel-title">How invitations work</h2><p class="panel-subtitle" style="line-height:1.7">Create a secure, single-use invite link, then send it to your teammate yourself. It expires after seven days. Admin and HR Manager accounts can view and manage the workspace HR data. You can remove access from this page at any time.</p></section>`}
async function loadTeam(){let body=document.getElementById('teamRows');if(!body)return;try{let r=await fetch('/api/team');if(!r.ok)throw new Error((await r.json()).error||'Could not load members');let data=await r.json(),canManage=['owner','admin'].includes(currentUser.role);body.innerHTML=data.users.map(u=>`<tr><td><div class="person-cell">${avatar(u.full_name,'purple')}<div><div class="person-name">${esc(u.full_name)} ${u.id===currentUser.id?'<span style="font-weight:500;color:#999aaa">(you)</span>':''}</div><div class="person-role">Member</div></div></div></td><td>${esc(u.email)}</td><td>${esc(u.role.replace('_',' ').replace(/\b\w/g,c=>c.toUpperCase()))}</td><td>${dateShort(u.created_at.slice(0,10))}</td><td>${!canManage||u.role==='owner'||u.id===currentUser.id?'':`<button class="button" data-action="remove-member" data-id="${esc(u.id)}">Remove access</button>`}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">No team members yet.</div></td></tr>'}catch(error){body.innerHTML=`<tr><td colspan="5"><div class="empty-state">${esc(error.message)}</div></td></tr>`}}
function helpPage(){return `${heading('Help & support','We’re here to help you get the most out of HRGenius.','')}<div class="analytics-grid"><section class="panel analytics-card"><span class="stat-icon icon-purple">✦</span><h2 class="panel-title" style="margin-top:12px">Getting started</h2><p class="panel-subtitle">Learn the basics and set up your HR workspace.</p><button class="button" data-action="help-guide">Browse quick start guide ↗</button></section><section class="panel analytics-card"><span class="stat-icon icon-blue">?</span><h2 class="panel-title" style="margin-top:12px">Talk to our team</h2><p class="panel-subtitle">Have a question? We’re happy to help.</p><a class="button" href="mailto:support@hrgenius.example">Contact support ↗</a></section></div>`}
function headcountSeries(count=6){let now=new Date(),months=[];for(let offset=count-1;offset>=0;offset--){let start=new Date(now.getFullYear(),now.getMonth()-offset,1),end=new Date(start.getFullYear(),start.getMonth()+1,0),cap=end>now?now:end,joined=db.employees.filter(e=>/^\d{4}-\d{2}-\d{2}$/.test(e.joined||'')).map(e=>({employee:e,date:new Date(`${e.joined}T00:00:00`)}));months.push({label:start.toLocaleDateString(undefined,{month:'short',...(count>6?{year:'2-digit'}:{})}),headcount:joined.filter(x=>x.date<=cap&&['Active','On leave'].includes(x.employee.status)).length,hires:joined.filter(x=>x.date.getFullYear()===start.getFullYear()&&x.date.getMonth()===start.getMonth()).length})}return {labels:months.map(x=>x.label),headcount:months.map(x=>x.headcount),hires:months.map(x=>x.hires)}}
function drawChart(){let c=document.getElementById('workforceChart');if(!c)return;let series=headcountSeries(chartMonths);drawLineChart(c,series.headcount,series.hires,series.labels)}
function drawAnalyticsCharts(){let c=document.getElementById('analyticsHeadcount'),period=document.getElementById('analyticsPeriod')?.value,count=period==='Last 12 months'?12:new Date().getMonth()+1,series=headcountSeries(count);if(c)drawLineChart(c,series.headcount,series.hires,series.labels);let d=document.getElementById('analyticsDepartments');if(d)drawDonut(d)}
function drawLineChart(canvas,a,b,labels){let rect=canvas.getBoundingClientRect();let w=rect.width,h=rect.height;if(!w||!h)return;let scale=devicePixelRatio||1;canvas.width=w*scale;canvas.height=h*scale;let ctx=canvas.getContext('2d');ctx.scale(scale,scale);let left=30,right=10,top=13,bottom=25,pw=w-left-right,ph=h-top-bottom,min=0,max=Math.max(1,...a)*1.25;ctx.font='9px DM Sans, sans-serif';ctx.textBaseline='middle';for(let i=0;i<4;i++){let y=top+ph*i/3;ctx.strokeStyle='#f0f0f5';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle='#a3a4b3';ctx.fillText(Math.round(max*(1-i/3)),0,y)}function line(values,color,fill){ctx.beginPath();values.forEach((v,i)=>{let x=left+pw*i/(values.length-1),y=top+ph*(1-(v-min)/(max-min));i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(fill){ctx.lineTo(left+pw,top+ph);ctx.lineTo(left,top+ph);ctx.closePath();let gr=ctx.createLinearGradient(0,top,0,h-bottom);gr.addColorStop(0,'#695be026');gr.addColorStop(1,'#695be000');ctx.fillStyle=gr;ctx.fill();ctx.beginPath();values.forEach((v,i)=>{let x=left+pw*i/(values.length-1),y=top+ph*(1-(v-min)/(max-min));i?ctx.lineTo(x,y):ctx.moveTo(x,y)})}ctx.strokeStyle=color;ctx.lineWidth=2;ctx.lineJoin='round';ctx.stroke();values.forEach((v,i)=>{let x=left+pw*i/(values.length-1),y=top+ph*(1-(v-min)/(max-min));ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke()})}line(a,'#695be0',true);line(b.map(v=>v*1.25),'#b7b1ff',false);labels.forEach((l,i)=>{let x=left+pw*i/(labels.length-1);ctx.fillStyle='#a3a4b3';ctx.textAlign='center';ctx.fillText(l,x,h-9)});canvas.onmousemove=e=>{let r=canvas.getBoundingClientRect(),x=e.clientX-r.left;let idx=Math.round((x-left)/pw*(labels.length-1));if(idx<0||idx>=labels.length)return;let t=canvas.parentElement.querySelector('.chart-tooltip');if(t){t.style.display='block';t.style.left=Math.min(x+10,w-110)+'px';t.style.top='10px';t.innerHTML=`<strong>${labels[idx]}</strong><br>Headcount: ${a[idx]} · New hires: ${b[idx]}`}};canvas.onmouseleave=()=>{let t=canvas.parentElement.querySelector('.chart-tooltip');if(t)t.style.display='none'}}
function drawDonut(canvas){let r=canvas.getBoundingClientRect(),scale=devicePixelRatio||1;if(!r.width)return;canvas.width=r.width*scale;canvas.height=r.height*scale;let x=canvas.getContext('2d');x.scale(scale,scale);let vals=[...new Set(db.employees.map(e=>e.department))].map(d=>[d,db.employees.filter(e=>e.department===d&&e.status==='Active').length]).filter(v=>v[1]),sum=vals.reduce((s,v)=>s+v[1],0),colors=['#695be0','#8b7fe9','#aaa1f1','#c4bff4','#dfdcfa','#eacb9c'];let cx=r.width/2,cy=r.height/2,rad=Math.min(r.height*.36,r.width*.20);let start=-Math.PI/2;vals.forEach((v,i)=>{let end=start+v[1]/sum*Math.PI*2;x.beginPath();x.arc(cx,cy,rad,start,end);x.strokeStyle=colors[i%colors.length];x.lineWidth=22;x.stroke();start=end});x.font='bold 20px Manrope';x.fillStyle='#22233a';x.textAlign='center';x.fillText(sum,cx,cy+5);x.font='9px DM Sans';x.fillStyle='#999aaa';x.fillText('people',cx,cy+19);let lx=14,ly=r.height-10;vals.forEach((v,i)=>{let row=i%3,col=Math.floor(i/3),xx=lx+col*110,yy=ly-row*17;x.fillStyle=colors[i%colors.length];x.fillRect(xx,yy-5,7,7);x.fillStyle='#77798e';x.textAlign='left';x.fillText(`${v[0]} ${v[1]}`,xx+11,yy)})}
function openModal(title,fields,submit,label='Save'){let root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" data-close-modal><form class="modal" id="activeForm"><div class="modal-head"><h2>${title}</h2><button type="button" class="modal-close" data-close-modal aria-label="Close">×</button></div><div class="modal-body"><div class="form-grid">${fields.map(f=>`<div class="form-field ${f.full?'full':''}"><label for="field-${f.name}">${f.label}${f.required?' *':''}</label>${f.options?`<select id="field-${f.name}" name="${f.name}" ${f.required?'required':''}>${f.options.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select>`:`<input id="field-${f.name}" name="${f.name}" type="${f.type||'text'}" placeholder="${esc(f.placeholder||'')}" ${f.required?'required':''} ${f.value!==undefined?`value="${esc(f.value)}"`:''} ${f.min!==undefined?`min="${f.min}"`:''} />`}</div>`).join('')}</div></div><div class="modal-foot"><button type="button" class="button" data-close-modal>Cancel</button><button class="button primary" type="submit">${label}</button></div></form></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal'))root.innerHTML=''});root.querySelector('form').addEventListener('submit',e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.currentTarget).entries());if(submit(data)===false)return;root.innerHTML=''})}
function toast(msg,ok=true){let root=document.getElementById('toastRoot'),t=document.createElement('div');t.className='toast'+(ok?' success':'');t.textContent=msg;root.append(t);setTimeout(()=>t.remove(),3200)}
function addEmployee(){openModal('Add employee',[{name:'name',label:'Full name',required:true,placeholder:'e.g. Alex Morgan'},{name:'email',label:'Work email',type:'email',required:true,placeholder:'alex@company.com'},{name:'role',label:'Job title',required:true,placeholder:'e.g. Product Designer'},{name:'department',label:'Department',options:['Engineering','Design','Marketing','People','Finance','Sales','Operations']},{name:'location',label:'Location',options:['New York','San Francisco','Austin','Chicago','Remote']},{name:'joined',label:'Start date',type:'date',required:true},{name:'salary',label:`Annual salary (${db.settings?.[0]?.currency||'USD'})`,type:'number',required:true,min:0},{name:'status',label:'Status',options:['Active','On leave','Inactive']}],d=>{if(db.employees.some(e=>e.email.trim().toLowerCase()===d.email.trim().toLowerCase())){toast('An employee with this email is already in the directory.',false);return false}let next=1024+Math.max(0,...db.employees.map(e=>Number(e.id.split('-')[1])-1024))+1;db.employees.unshift({id:`HR-${next}`,name:d.name,email:d.email,role:d.role,department:d.department,location:d.location,joined:d.joined,salary:Number(d.salary),status:d.status,color:['pink','blue','green','orange','purple'][db.employees.length%5]});saveData();render();toast(`${d.name} added to your team`)},'Add employee')}
function addCandidate(){openModal('Add candidate',[{name:'name',label:'Full name',required:true},{name:'role',label:'Position',required:true,placeholder:'e.g. Product Designer'},{name:'email',label:'Email',type:'email',required:true},{name:'stage',label:'Pipeline stage',options:['Applied','Screening','Interview','Offer']},{name:'score',label:'Match score (%)',type:'number',min:0}],d=>{db.candidates.unshift({id:Date.now(),name:d.name,initials:initials(d.name),role:d.role,stage:d.stage,date:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'}),createdAt:new Date().toISOString(),score:`${d.score||80}%`,color:'purple'});saveData();render();toast(`${d.name} added to recruitment pipeline`)},'Add candidate')}
function addGoal(){openModal('Add team goal',[{name:'title',label:'Goal',required:true,full:true,placeholder:'What do you want to accomplish?'},{name:'owner',label:'Owner',options:db.employees.map(e=>e.name)},{name:'progress',label:'Progress (%)',type:'number',min:0}],d=>{db.goals.unshift({title:d.title,owner:d.owner,progress:Number(d.progress||0),status:'In progress'});saveData();render();toast('Goal added')},'Add goal')}
function addLeave(){if(!db.employees.length){toast('Add an employee before creating a leave request.',false);return}openModal('Request time off',[{name:'employee',label:'Employee',options:db.employees.map(e=>e.name)},{name:'type',label:'Leave type',options:['Annual leave','Sick leave','Personal leave','Unpaid leave']},{name:'start',label:'First day',type:'date',required:true},{name:'end',label:'Last day',type:'date',required:true},{name:'notes',label:'Notes',full:true,placeholder:'Optional note for the approver'}],d=>{if(d.end<d.start){toast('The last day must be on or after the first day.',false);return}let person=db.employees.find(e=>e.name===d.employee),days=Math.round((Date.parse(d.end+'T00:00:00Z')-Date.parse(d.start+'T00:00:00Z'))/86400000)+1;db.leaves.unshift({id:crypto.randomUUID(),employee:d.employee,type:d.type,start:d.start,end:d.end,days,status:'Pending',notes:d.notes,createdAt:new Date().toISOString().slice(0,10),color:person?.color||'purple'});saveData();render();toast('Leave request submitted')},'Submit request')}
function addOnboarding(){openModal('Start onboarding',[{name:'name',label:'New teammate name',required:true,placeholder:'Alex Morgan'},{name:'email',label:'Work email',type:'email',required:true},{name:'role',label:'Job title',required:true},{name:'department',label:'Department',options:['Engineering','Design','Marketing','People','Finance','Sales','Operations']},{name:'startDate',label:'Start date',type:'date',required:true}],d=>{db.onboarding.unshift({id:crypto.randomUUID(),name:d.name,email:d.email,role:d.role,department:d.department,startDate:d.startDate,tasks:[{title:'Send welcome email',done:false},{title:'Prepare laptop and equipment',done:false},{title:'Set up accounts and access',done:false},{title:'Schedule team introductions',done:false},{title:'Review first-week plan',done:false}]});saveData();render();toast(`${d.name} added to onboarding`)},'Create checklist')}
function addReview(){openModal('Add performance review',[{name:'employee',label:'Employee',options:db.employees.map(e=>e.name)},{name:'score',label:'Rating (1–5)',type:'number',min:1},{name:'progress',label:'Goal progress (%)',type:'number',min:0}],d=>{let e=db.employees.find(x=>x.name===d.employee);db.reviews.unshift({name:d.employee,role:e?.role||'Team member',score:Number(d.score||4),progress:Number(d.progress||0),color:e?.color||'purple'});saveData();render();toast('Performance review added')},'Add review')}
function candidateStage(id){let c=db.candidates.find(x=>x.id==id),stages=['Applied','Screening','Interview','Offer'];if(!c)return;let next=stages[Math.min(stages.indexOf(c.stage)+1,stages.length-1)];if(c.stage==='Offer'){if(confirm(`Mark ${c.name} as hired and remove from the pipeline?`)){db.candidates=db.candidates.filter(x=>x.id!=id);saveData();render();toast(`${c.name} marked as hired`)}}else{c.stage=next;saveData();render();toast(`${c.name} moved to ${next}`)}}
function downloadFile(content,filename,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your download is ready')}
function csvExport(rows,filename){let csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadFile('\ufeff'+csv,filename,'text/csv;charset=utf-8;')}
function exportLeaveCalendar(){let approved=db.leaves.filter(l=>l.status==='Approved'&&l.start&&l.end),escapeIcs=x=>String(x||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),plusDay=value=>{let d=new Date(`${value}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10).replace(/-/g,'')};let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HRGenius//Time Off//EN','CALSCALE:GREGORIAN',...approved.flatMap(l=>['BEGIN:VEVENT',`UID:${escapeIcs(l.id)}@hrgenius`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${l.start.replace(/-/g,'')}`,`DTEND;VALUE=DATE:${plusDay(l.end)}`,`SUMMARY:${escapeIcs(`${l.employee} · ${l.type}`)}`,`DESCRIPTION:${escapeIcs(`${l.days||1} day(s) of approved leave`)}`,'END:VEVENT']),'END:VCALENDAR'];downloadFile(lines.join('\r\n'),'hrgenius-leave-calendar.ics','text/calendar;charset=utf-8')}
function exportEmployees(){csvExport([['Employee ID','Name','Email','Role','Department','Location','Start date',`Annual salary (${db.settings?.[0]?.currency||'USD'})`,'Status'],...db.employees.map(e=>[e.id,e.name,e.email,e.role,e.department,e.location,e.joined,e.salary,e.status])],'hrgenius-employees.csv')}
function menuFor(button,items){document.querySelector('.icon-menu')?.remove();let m=document.createElement('div');m.className='icon-menu';m.style.top=(button.getBoundingClientRect().bottom+window.scrollY)+'px';m.style.right=(innerWidth-button.getBoundingClientRect().right)+'px';m.innerHTML=items.map(it=>`<button data-menu-action="${it.action}">${it.label}</button>`).join('');document.body.append(m);m.onclick=e=>{let b=e.target.closest('[data-menu-action]');if(b){document.dispatchEvent(new CustomEvent('menuaction',{detail:{action:b.dataset.menuAction,id:button.dataset.id}}));m.remove()}};setTimeout(()=>document.addEventListener('click',function f(e){if(!m.contains(e.target)&&e.target!==button){m.remove();document.removeEventListener('click',f)}},{once:true}),0)}
document.addEventListener('click',e=>{let page=e.target.closest('[data-page]');if(page){e.preventDefault();setPage(page.dataset.page);return}let b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'add-employee':addEmployee();break;case'add-candidate':addCandidate();break;case'add-goal':addGoal();break;case'add-review':addReview();break;case'candidate-stage':candidateStage(b.dataset.id);break;case'candidate-menu':menuFor(b,[{action:'advance-candidate',label:'Move to next stage'},{action:'delete-candidate',label:'Remove candidate'}]);break;case'employee-menu':menuFor(b,[{action:'edit-employee',label:'Edit employee'},{action:'toggle-employee',label:'Change status'},{action:'delete-employee',label:'Delete employee'}]);break;case'run-payroll':{let active=db.employees.filter(x=>x.status==='Active'),gross=Math.round(active.reduce((s,x)=>s+Number(x.salary||0),0)/12),now=new Date(),period=now.toLocaleDateString('en-US',{month:'long',year:'numeric'});if(db.payruns.some(r=>r.period===period&&r.status==='Draft')){toast('A draft already exists for this pay period.',false);break}if(confirm(`Create a ${period} payroll draft for ${active.length} active employees? Gross pay estimate: ${money(gross)}. This demo does not transfer money.`)){db.payruns.unshift({id:`PR-${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,period,employees:active.length,gross,payDate:new Date(Date.UTC(now.getFullYear(),now.getMonth()+1,0)).toISOString().slice(0,10),status:'Draft'});saveData();render();toast(`${period} payroll draft created for review`)}break}case'approve-payroll':{let run=db.payruns.find(r=>r.id===b.dataset.id);if(run&&confirm(`Mark the ${run.period} payroll draft as approved?`)){run.status='Approved';saveData();render();toast('Payroll marked approved. No payments were sent.')}break}case'rename-workspace':openModal('Rename workspace',[{name:'name',label:'Workspace name',required:true,value:'Acme Studio'}],d=>{document.querySelector('.workspace-copy strong').textContent=d.name;toast('Workspace name updated')});break;case'help-guide':toast('Quick start: add employees, build your hiring pipeline, and review your people analytics.');break;}});
document.addEventListener('menuaction',e=>{let {action,id}=e.detail;if(action==='advance-candidate')candidateStage(id);if(action==='delete-candidate'){let c=db.candidates.find(x=>x.id==id);if(c&&confirm(`Remove ${c.name} from the pipeline?`)){db.candidates=db.candidates.filter(x=>x.id!=id);saveData();render();toast('Candidate removed')}}if(action==='delete-employee'){let emp=db.employees.find(x=>x.id===id);if(emp&&confirm(`Delete ${emp.name} from your employee directory?`)){db.employees=db.employees.filter(x=>x.id!==id);saveData();render();toast('Employee deleted')}}if(action==='toggle-employee'){let emp=db.employees.find(x=>x.id===id);if(emp){emp.status=emp.status==='Active'?'Inactive':'Active';saveData();render();toast(`${emp.name}'s status updated`)}}if(action==='edit-employee'){let emp=db.employees.find(x=>x.id===id);if(emp)openModal('Edit employee',[{name:'name',label:'Full name',required:true,value:emp.name},{name:'email',label:'Work email',type:'email',required:true,value:emp.email},{name:'role',label:'Job title',required:true,value:emp.role},{name:'department',label:'Department',options:['Engineering','Design','Marketing','People','Finance','Sales','Operations']},{name:'location',label:'Location',options:['New York','San Francisco','Austin','Chicago','Remote']},{name:'joined',label:'Start date',type:'date',required:true,value:emp.joined},{name:'salary',label:`Annual salary (${db.settings?.[0]?.currency||'USD'})`,type:'number',required:true,value:emp.salary},{name:'status',label:'Status',options:['Active','On leave','Inactive']}],d=>{Object.assign(emp,{name:d.name,email:d.email,role:d.role,department:d.department,location:d.location,joined:d.joined,salary:Number(d.salary),status:d.status});saveData();render();toast('Employee record updated')},'Save changes')}});
document.getElementById('pageContent').addEventListener('input',e=>{if(e.target.id==='employeeSearch'){employeeQuery=e.target.value;let pos=e.target.selectionStart;render();let input=document.getElementById('employeeSearch');input.focus();input.setSelectionRange(pos,pos)}});
document.getElementById('pageContent').addEventListener('change',e=>{if(e.target.id==='employeeFilter'){employeeFilter=e.target.value;render()}if(e.target.id==='roleFilter'){recruitmentFilter=e.target.value;render()}if(e.target.id==='chartPeriod'){chartMonths=e.target.value==='Last 12 months'?12:6;drawChart()}if(e.target.id==='analyticsPeriod')drawAnalyticsCharts()});
document.getElementById('pageContent').addEventListener('click',e=>{let tab=e.target.closest('[data-settings-tab]');if(tab){settingsTab=tab.dataset.settingsTab;render();return}let exportButton=e.target.closest('[data-settings-export]');if(exportButton){let type=exportButton.dataset.settingsExport;if(type==='employees')exportEmployees();if(type==='payroll')csvExport([['ID','Period','Employees','Gross pay','Pay date','Status'],...(db.payruns||[]).map(p=>[p.id,p.period,p.employees,p.gross,p.payDate,p.status])],'hrgenius-payroll.csv');if(type==='backup')downloadFile(JSON.stringify({workspace:currentUser.company,exportedAt:new Date().toISOString(),data:db},null,2),'hrgenius-workspace-backup.json','application/json');if(type==='calendar')exportLeaveCalendar();return}if(e.target.closest('#exportEmployees'))exportEmployees();if(e.target.closest('#salaryExport'))csvExport([['Department','Employees','Average salary','Annual total'],...[...new Set(db.employees.map(x=>x.department))].map(d=>{let a=db.employees.filter(x=>x.department===d&&x.status==='Active'),s=a.reduce((n,x)=>n+Number(x.salary||0),0);return[d,a.length,a.length?s/a.length:0,s]})],'hrgenius-salary-report.csv');if(e.target.closest('#analyticsExport'))csvExport([['Metric','Value'],['Active headcount',db.employees.filter(x=>x.status==='Active').length],['Average annual salary',Math.round(db.employees.filter(x=>x.status==='Active').reduce((s,x)=>s+Number(x.salary||0),0)/Math.max(1,db.employees.filter(x=>x.status==='Active').length))],['Open roles',new Set(db.candidates.map(x=>x.role)).size],['Candidates in pipeline',db.candidates.length]],'hrgenius-analytics.csv');if(e.target.closest('#payrollExport')){let total=db.employees.filter(x=>x.status==='Active').reduce((s,x)=>s+Number(x.salary||0),0);csvExport([['Pay period','Employees','Estimated gross pay','Pay date','Status'],['September 2026',db.employees.length,Math.round(total/12),'September 30, 2026','Paid'],['October 2026',db.employees.length,Math.round(total/12),'October 31, 2026','Upcoming']],'hrgenius-payroll.csv')}});
document.getElementById('globalSearch').addEventListener('input',e=>{let q=e.target.value.trim();if(q){employeeQuery=q;setPage('employees');let inp=document.getElementById('employeeSearch');if(inp)inp.value=q}else if(currentPage==='employees'){employeeQuery='';render()}});
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){e.target.value='';employeeQuery='';if(currentPage==='employees')render()}if(e.key==='Enter'&&e.target.value.trim()){employeeQuery=e.target.value.trim();setPage('employees')}});
document.addEventListener('click',async e=>{let button=e.target.closest('[data-action]'),action=button?.dataset.action;if(action==='invite-member'){let roles=['hr_manager'];if(['owner','admin'].includes(currentUser.role))roles.push('admin');openModal('Invite a teammate',[{name:'email',label:'Work email',type:'email',required:true,placeholder:'teammate@company.com'},{name:'role',label:'Workspace role',options:roles}],async data=>{try{let result=await apiRequest('/api/invitations',{method:'POST',body:JSON.stringify(data)});showInviteResult(result.inviteUrl,result.email)}catch(error){toast(error.message,false)}},'Create invite link')}if(action==='remove-member'&&confirm('Remove this person from the workspace? Their access will end immediately.'))try{await apiRequest(`/api/team/${encodeURIComponent(button.dataset.id)}`,{method:'DELETE'});toast('Workspace access removed');loadTeam()}catch(error){toast(error.message,false)}if(action==='add-leave')addLeave();if(action==='leave-decision'){let record=db.leaves.find(l=>l.id===button.dataset.id);if(record){record.status=button.dataset.status;saveData();render();toast(`Leave request ${record.status.toLowerCase()}`)}}if(action==='add-onboarding')addOnboarding();if(action==='complete-onboarding'){let o=db.onboarding.find(x=>x.id===button.dataset.id);if(!o)return;if(o.tasks.some(t=>!t.done)){toast('Complete every checklist item before adding this teammate.',false);return}if(db.employees.some(p=>p.email.toLowerCase()===o.email.toLowerCase())){toast('An employee with this email is already in the directory.',false);return}db.employees.unshift({id:`HR-${1025+db.employees.length}`,name:o.name,email:o.email,role:o.role,department:o.department,location:'Remote',joined:o.startDate,salary:0,status:'Active',color:'purple'});db.onboarding=db.onboarding.filter(x=>x.id!==o.id);saveData();setPage('employees');toast(`${o.name} added to the employee directory`)}});
document.getElementById('pageContent').addEventListener('change',e=>{if(e.target.id==='leaveFilter'){let body=document.getElementById('leaveRows');if(body)body.innerHTML=leaveRows(e.target.value)}if(e.target.matches('[data-action="onboarding-task"]')){let o=db.onboarding.find(x=>x.id===e.target.dataset.id),task=o?.tasks[Number(e.target.dataset.index)];if(task){task.done=e.target.checked;saveData();render()}}});
document.getElementById('pageContent').addEventListener('submit',async e=>{if(e.target.id==='settingsForm'){e.preventDefault();await saveSettingsForm(e.target);return}if(e.target.id!=='changePasswordForm')return;e.preventDefault();let payload=Object.fromEntries(new FormData(e.target).entries());try{let result=await apiRequest('/api/auth/password',{method:'POST',body:JSON.stringify(payload)});csrfToken=result.csrfToken;e.target.reset();toast('Password changed. Other sessions were signed out.')}catch(error){toast(error.message,false)}});
