document.getElementById('notificationButton').addEventListener('click',()=>toast('You’re all caught up.'));
document.getElementById('helpButton').addEventListener('click',()=>setPage('help'));
document.getElementById('profileButton').addEventListener('click',showAccountMenu);
document.getElementById('topProfile').addEventListener('click',showAccountMenu);
window.addEventListener('resize',()=>{if(currentPage==='dashboard')drawChart();if(currentPage==='analytics')drawAnalyticsCharts()});
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(['dashboard','employees','recruitment','payroll','performance','leave','onboarding','analytics','settings','team','help'].includes(p)&&p!==currentPage&&currentUser)setPage(p)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch').focus()}if(e.key==='Escape')document.getElementById('modalRoot').innerHTML=''});
function showAccountMenu(){document.querySelector('.logout-menu')?.remove();let m=document.createElement('div');m.className='logout-menu';m.innerHTML=`<button id="logoutAction">Sign out of ${esc(currentUser?.company||'HRGenius')}</button>`;document.body.append(m);m.querySelector('#logoutAction').addEventListener('click',logout);setTimeout(()=>document.addEventListener('click',function close(e){if(!m.contains(e.target)){m.remove();document.removeEventListener('click',close)}},{once:true}),0)}
async function apiRequest(path,options={}){let headers={...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';if(csrfToken&&options.method&&options.method!=='GET')headers['X-CSRF-Token']=csrfToken;let response=await fetch(path,{credentials:'same-origin',...options,headers});let data=await response.json().catch(()=>({error:'The server returned an invalid response.'}));if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data}
function showAuthError(message){let box=document.getElementById('authError');if(box){box.textContent=message;box.classList.add('show')}}
async function showAuth(mode='login',invite=null){document.body.classList.remove('authenticated');let root=document.getElementById('authRoot'),inviteToken=new URLSearchParams(location.search).get('invite');if(inviteToken&&!invite){try{invite=await apiRequest(`/api/invitations/${encodeURIComponent(inviteToken)}`);mode='signup'}catch(error){mode='signup';invite={error:error.message}}}let joining=Boolean(inviteToken),signup=mode==='signup';root.innerHTML=`<div class="auth-screen"><section class="auth-brand-panel"><a class="auth-brand" href="#"><span class="brand-mark">h</span><span>hr<span>genius</span></span></a><div class="auth-brand-message"><div class="eyebrow">PEOPLE, MADE SIMPLER</div><h1>Great work starts with a great team.</h1><p>Bring your people operations together. Manage your team, build thoughtful hiring processes, and help everyone do their best work.</p></div><div class="auth-brand-footer">HRGenius · Human resources, thoughtfully managed</div></section><section class="auth-form-panel"><div class="auth-card"><h2>${joining?'Join your workspace':signup?'Create your workspace':'Welcome back'}</h2><p>${joining?`You’ve been invited to ${esc(invite?.company||'a HRGenius workspace')}. Create your account to join.`:signup?'Start your HRGenius workspace. You can invite your team after setup.':'Sign in to continue to your HRGenius workspace.'}</p>${invite?.error?`<div class="auth-invite-note">${esc(invite.error)}</div>`:joining?`<div class="auth-invite-note">Invitation for ${esc(invite?.email||'')} · ${esc((invite?.role||'').replace('_',' '))}</div>`:''}<div class="auth-error" id="authError"></div><form id="authForm" class="auth-fields"><input type="hidden" name="invite" value="${joining?esc(inviteToken):''}">${signup?`<label class="auth-field">Your name<input name="name" autocomplete="name" required minlength="2" maxlength="100" placeholder="Jordan Davis"></label>`:''}<label class="auth-field">Work email<input name="email" type="email" autocomplete="email" required ${joining?`value="${esc(invite?.email||'')}" readonly`:''} placeholder="you@company.com"></label>${signup&&!joining?`<label class="auth-field">Company or workspace<input name="company" required minlength="2" maxlength="120" placeholder="Acme Studio"></label>`:''}<label class="auth-field">Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required ${signup?'minlength="12"':''} maxlength="200" placeholder="${signup?'At least 12 characters':'Your password'}"></label><button class="auth-submit" type="submit">${signup?'Create account':'Sign in'}</button></form>${signup?`<div class="auth-terms">Use a unique password of at least 12 characters. Keep account invitations private.</div>`:''}<div class="auth-switch">${signup?'Already have an account?':'New to HRGenius?'} <button id="authSwitch">${signup?'Sign in':'Create a workspace'}</button></div></div></section></div>`;root.querySelector('#authSwitch').addEventListener('click',()=>showAuth(signup?'login':'signup'));root.querySelector('#authForm').addEventListener('submit',async e=>{e.preventDefault();let form=e.currentTarget,button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Please wait…';let payload=Object.fromEntries(new FormData(form).entries());try{let data=await apiRequest(signup?'/api/auth/signup':'/api/auth/login',{method:'POST',headers:{},body:JSON.stringify(payload)});await enterWorkspace(data)}catch(error){showAuthError(error.message);button.disabled=false;button.textContent=signup?'Create account':'Sign in'}})}
async function enterWorkspace(data){currentUser=data.user;csrfToken=data.csrfToken;let dataset=await apiRequest('/api/data');db={...structuredClone(seed),...dataset};let hadSettings=Array.isArray(dataset.settings)&&dataset.settings.length>0;workspaceSettings();lastSavedSnapshot=JSON.stringify(db);apiReady=true;if(!hadSettings)saveData();document.body.classList.add('authenticated');document.getElementById('authRoot').innerHTML='';document.querySelector('.workspace-copy strong').textContent=currentUser.company;document.getElementById('workspaceCrumb').textContent=currentUser.company;document.getElementById('sideUserName').textContent=currentUser.name;document.getElementById('topUserName').textContent=currentUser.name;let roleName=currentUser.role.replace('_',' ').replace(/\b\w/g,c=>c.toUpperCase());document.getElementById('sideUserRole').textContent=roleName;document.querySelectorAll('.top-profile .avatar,.profile-card .avatar').forEach(el=>el.textContent=initials(currentUser.name));history.replaceState({},'',location.pathname+(location.hash||'#dashboard'));setPage(['dashboard','employees','recruitment','payroll','performance','leave','onboarding','analytics','settings','team','help'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard')}
async function logout(){try{await apiRequest('/api/auth/logout',{method:'POST'})}catch(error){console.error(error)}currentUser=null;csrfToken='';apiReady=false;lastSavedSnapshot='';db=loadData();document.body.classList.remove('authenticated');document.querySelector('.logout-menu')?.remove();history.replaceState({},'',location.pathname);showAuth('login')}
function showInviteResult(url,email){let root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal invite-result"><div class="modal-head"><h2>Invitation link created</h2><button class="modal-close" data-close-modal>×</button></div><div class="modal-body"><p>Send this one-time link to <strong>${esc(email)}</strong>. It expires in seven days and can only be used once.</p><textarea id="inviteUrl" readonly>${esc(url)}</textarea></div><div class="modal-foot"><button class="button" data-close-modal>Done</button><button class="button primary" id="copyInvite">Copy invite link</button></div></div></div>`;root.querySelectorAll('[data-close-modal]').forEach(el=>el.addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal'))root.innerHTML=''}));root.querySelector('#copyInvite').addEventListener('click',async()=>{let field=root.querySelector('#inviteUrl');try{await navigator.clipboard.writeText(url);toast('Invitation link copied')}catch{field.select();document.execCommand('copy');toast('Invitation link copied')}})}
async function startApp(){try{let data=await apiRequest('/api/auth/session');if(data.user){try{await enterWorkspace(data);return}catch(error){console.error(error)}}let inviteToken=new URLSearchParams(location.search).get('invite');await showAuth(inviteToken?'signup':'login')}catch(error){document.getElementById('authRoot').innerHTML=`<div class="auth-screen"><section class="auth-form-panel"><div class="auth-card"><h2>HRGenius server unavailable</h2><p>Start the app in the project folder with <code>npm start</code>, then refresh this page.</p><button class="auth-submit" id="retryAuth">Try again</button></div></section></div>`;document.getElementById('retryAuth')?.addEventListener('click',()=>location.reload());document.body.classList.remove('authenticated')}}
const renderAuth=showAuth;
showAuth=async function(mode='login',invite=null){let token=new URLSearchParams(location.search).get('invite');if(token&&!invite){try{invite=await apiRequest(`/api/invitations/${encodeURIComponent(token)}`);mode='signup'}catch(error){history.replaceState({},'',location.pathname+location.hash);invite={error:error.message};mode='signup'}}return renderAuth(mode,invite)};
startApp();
